//
// @param x {int}  Input number.
//
// @return {int} largest proper divisor.
largest_divisor:{[x]
    if[x<=1; :0];  // Handle edge case where no proper divisor exists
    limit: floor sqrt x;
    / Find the smallest divisor d in range [2; limit]. 
    / If found, x % d is the smallest prime factor.
    / If not found (x is prime), the smallest prime factor is x itself.
