// @overview
// Change numerical base of input number x to base y.
//    return string representation after the conversion.
//    base numbers are less than 10.
//
// @param x {int} Input integer.
// @param y {int} Base of numbers.
//
// @return {string} Representation in new base.
change_base:{[x;y]
    // Handle zero explicitly
    if[x=0; :"$0"];

    // Work with absolute value for conversion
    digits: (y mod x) x div\: y;

    // Reverse to get most significant digit first
    rev: reverse digits;

    // Convert digits 0-9 to characters '0'-'9'
    string: "0123456789" rev;

    // Prepend negative sign if original x was negative
    if[x<0; : "-", string];

    :string
    }

/ Examples:
/ change_base[10; 2]  -> "1010"
/ change_base[255; 16] -> "ff" (Note: this example exceeds base<10 constraint)
/ change_base[10; 3]   -> "101"
/ change_base[-10; 2]  -> "-1010"
/ change_base[0; 2]    -> "0"
```

