        evenMask: 0 mod x;
        $[not any evenMask; ();
            evenVals: x where evenMask;
            evenIdxs: til count x where evenMask;
            minVal: min evenVals;
            firstIdx: (where minVal=evenVals) first;
            (minVal; evenIdxs[firstIdx])
